    private static Block observer;private static BlockPos publicationRoot;private static boolean publicationFault;private static FixtureDoor block;private static NativeDoorItem item;private static BlockEntityType<NativeProgrammableDoorEntity> type;private static MenuType<NativeDoorMenu> menus;
    private static int checks,fault,dropCount;private static BlockPos trackedDrop;private static BlockPos faultRoot;private static final BlockPos BASE=new BlockPos(3300,110,3300),SAVED=BASE.east(10);
    private static String phase(){return System.getProperty("vandorlabs.transmitterPhase","");}
    private static boolean enabled(){return phase().startsWith("door-lifecycle-");}
    private static void need(boolean value,String message){checks++;if(!value)throw new AssertionError("Door lifecycle: "+message);}
    private static final class Counting extends NativeProgrammableDoorEntity {
        boolean ready;int dirty,models;
        Counting(BlockPos pos,BlockState state){super(type,pos,state,false,true);ready=true;}
        private void complete(){if(ready)need(getModelData().get(SETTINGS)==settings()&&getModelData().get(VISUAL).settings()==settings(),"complete immutable model snapshot before callback");}
        @Override public void setChanged(){complete();dirty++;super.setChanged();}
        @Override public void requestModelDataUpdate(){complete();models++;super.requestModelDataUpdate();}
        void reset(){dirty=models=0;}
    }
    private static final class FixtureDoor extends NativeProgrammableDoorBlock {
        FixtureDoor(){super(Properties.of().noOcclusion().dynamicShape(),()->type,()->menus,()->item,true);}
        @Override public BlockEntity newBlockEntity(BlockPos pos,BlockState state){return new Counting(pos,state);}
        @Override protected MapCodec<? extends BaseEntityBlock> codec(){return MapCodec.unit(this);}
        // The fixture checks inventory/structure/menu behavior, not the separately owned authored shapes.
        @Override protected VoxelShape orphanShape(BlockState state,boolean collision){return Block.box(0,0,5,16,16,11);}
        @Override protected VoxelShape doorShape(NativeDoorSettings settings,BlockState state,boolean collision){return collision&&state.getValue(OPEN)&&settings.door().sliding?Shapes.empty():Block.box(0,0,5,16,16,11);}
        @Override protected boolean controlPanelHit(NativeDoorSettings settings,BlockState state,com.vandorlabs.render.SpaceDoorControlPanel.Side side,BlockHitResult hit,BlockPos lower){return false;}
        @Override protected boolean securityOpen(NativeProgrammableDoorEntity host){return host.securityOpen();}
        @Override protected InteractionResult credentialInteraction(NativeProgrammableDoorEntity host,Player player,InteractionHand hand,BlockHitResult hit,boolean panelHit){return player instanceof net.minecraft.server.level.ServerPlayer server&&host.interactCredential(0,server,hand)?InteractionResult.CONSUME:InteractionResult.FAIL;}
        @Override protected boolean stagePart(net.minecraft.world.level.Level level,BlockPos pos,BlockState state){if(fault!=0&&pos.equals(faultRoot.above())){if(fault==2||fault==3)super.stagePart(level,pos,state);if(fault==3)throw new IllegalStateException("fixture stage after actual upper publication");return false;}return super.stagePart(level,pos,state);}
        @Override protected boolean restorePart(net.minecraft.world.level.Level level,BlockPos pos,BlockState old){if(fault==4&&pos.equals(faultRoot))return false;return super.restorePart(level,pos,old);}
    }
    @EventBusSubscriber(modid="vandorlabs",bus=EventBusSubscriber.Bus.MOD)
    public static final class Registration {
        @SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;var id=ResourceLocation.fromNamespaceAndPath("vandorlabs","ordinary_door_lifecycle_fixture");event.register(Registries.BLOCK,h->{block=new FixtureDoor();h.register(id,block);observer=new Block(BlockBehaviour.Properties.of()){@Override protected void neighborChanged(BlockState state,net.minecraft.world.level.Level level,BlockPos pos,Block changed,BlockPos from,boolean moving){if(publicationFault&&pos.equals(publicationRoot.north())&&from.equals(publicationRoot))throw new IllegalStateException("fixture observer after complete staged publication");}};h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","door_publication_observer_fixture"),observer);});event.register(Registries.ITEM,h->{item=new NativeDoorItem(block,new Item.Properties());h.register(id,item);});event.register(Registries.BLOCK_ENTITY_TYPE,h->{type=BlockEntityType.Builder.<NativeProgrammableDoorEntity>of((pos,state)->new Counting(pos,state),block).build(null);h.register(id,type);});event.register(Registries.MENU,h->{menus=net.neoforged.neoforge.common.extensions.IMenuTypeExtension.create((window,inventory,b)->new NativeDoorMenu(menus,window,inventory,b.readBlockPos()));h.register(id,menus);});}
    }
    @SubscribeEvent public static void join(net.neoforged.neoforge.event.entity.EntityJoinLevelEvent event){if(enabled()&&trackedDrop!=null&&!event.isCanceled()&&event.getEntity() instanceof ItemEntity entity&&entity.getItem().is(item)&&entity.position().distanceToSqr(Vec3.atCenterOf(trackedDrop))<4)dropCount+=entity.getItem().getCount();}
    private static NativeProgrammableDoorEntity host(ServerLevel level,BlockPos pos){return (NativeProgrammableDoorEntity)level.getBlockEntity(pos);}
    private static void clear(ServerLevel level,BlockPos root){fault=0;level.getChunkAt(root);for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++){for(int y=0;y<3;y++)level.setBlock(root.offset(x,y,z),Blocks.AIR.defaultBlockState(),Block.UPDATE_CLIENTS);level.setBlock(root.offset(x,-1,z),Blocks.STONE.defaultBlockState(),Block.UPDATE_CLIENTS);}for(var entity:level.getEntitiesOfClass(ItemEntity.class,new AABB(root).inflate(5)))entity.discard();}
    private static InteractionResult place(ServerLevel level,net.minecraft.server.level.ServerPlayer actor,BlockPos pos,ItemStack held,double z){actor.setPos(pos.getX()+.5,pos.getY(),pos.getZ()+2.5);actor.setYRot(0);actor.setXRot(0);actor.setShiftKeyDown(false);actor.setGameMode(GameType.SURVIVAL);actor.setItemInHand(InteractionHand.MAIN_HAND,held);return held.useOn(new UseOnContext(actor,InteractionHand.MAIN_HAND,new BlockHitResult(new Vec3(pos.getX()+.5,pos.getY(),pos.getZ()+z),Direction.UP,pos.below(),false)));}
    private static BlockHitResult hit(BlockPos pos){return new BlockHitResult(Vec3.atCenterOf(pos),Direction.NORTH,pos,false);}
